package swati4star.createpdf.interfaces;

/**
 * Implemented by fragments which want to intercept the back button press,
 * for example to collapse an expanded bottom sheet instead of being
 * replaced by the home fragment.
 */
public interface OnBackPressedInterface {

    /**
     * Called by the host activity whenever the back button is pressed.
     *
     * @return true if the fragment consumed the back press,
     * false to let the activity handle it as usual
     */
    boolean onBackPressed();
}

