209	     */
210	    private void handleReceivedImagesIntent(Fragment fragment) {
211	        Intent intent = getIntent();
212	        String action = intent.getAction();
213	        String type = intent.getType();
214	
215	        if (type == null || !type.startsWith("image/"))
216	            return;
217	
218	        if (Intent.ACTION_SEND_MULTIPLE.equals(action)) {
219	            handleSendMultipleImages(intent, fragment); // Handle multiple images
220	        } else if (Intent.ACTION_SEND.equals(action)) {
221	            handleSendImage(intent, fragment); // Handle single image
222	        }
223	    }
