137	    public void onActivityResult(int requestCode, int resultCode, Intent data) throws NullPointerException {
138	        if (data == null || resultCode != RESULT_OK )
139	            return;
140	        if (requestCode == INTENT_REQUEST_PICKFILE_CODE) {
141	            mUri = data.getData();
142	            setTextAndActivateButtons(getFilePath(data.getData()));
143	        } else if (requestCode == INTENT_REQUEST_REARRANGE_PDF) {
144	            String pages = data.getStringExtra(RESULT);
145	
146	            if (mPath == null)
147	                return;
148	
149	            Log.v("output", pages + " ");
150	            String outputPath = mPath.replace(mActivity.getString(R.string.pdf_ext),
151	                    "_edited" + pages + mActivity.getString(R.string.pdf_ext));
152	            if (mPDFUtils.isPDFEncrypted(mPath)) {
153	                showSnackbar(mActivity, R.string.encrypted_pdf);
154	                return;
155	            }
156	
157	            if (mPDFUtils.reorderRemovePDF(mPath, outputPath, pages)) {
158	                viewPdfButton(outputPath);
159	            }
160	            resetValues();
161	        }
162	    }
