164	    @OnClick(R.id.pdfCreate)
165	    public void parse() {
166	        hideKeyboard(mActivity);
167	        if (mOperation.equals(COMPRESS_PDF)) {
168	            compressPDF();
169	            return;
170	        }
171	
172	        PDFEncryptionUtility pdfEncryptionUtility = new PDFEncryptionUtility(mActivity);
173	        if (mOperation.equals(ADD_PWD)) {
174	            if (!mPDFUtils.isPDFEncrypted(mPath)) {
175	                pdfEncryptionUtility.setPassword(mPath, null, new ArrayList<>());
176	            } else {
177	                showSnackbar(mActivity, R.string.encrypted_pdf);
178	            }
179	            return;
180	        }
181	
182	        if (mOperation.equals(REMOVE_PWd)) {
183	            if (mPDFUtils.isPDFEncrypted(mPath)) {
184	                pdfEncryptionUtility.removePassword(mPath, null, new ArrayList<>());
185	            } else {
186	                showSnackbar(mActivity, R.string.not_encrypted);
187	            }
188	            return;
189	        }
190	
191	        // Render pdf pages as bitmap
192	        ArrayList<Bitmap> bitmaps = new ArrayList<>();
193	        ParcelFileDescriptor fileDescriptor = null;
194	        try {
195	            if (mUri != null)
196	                fileDescriptor = mActivity.getContentResolver().openFileDescriptor(mUri, "r");
197	            else if (mPath != null)
198	                fileDescriptor = ParcelFileDescriptor.open(new File(mPath), MODE_READ_ONLY);
199	            if (fileDescriptor != null) {
200	                PdfRenderer renderer = new PdfRenderer(fileDescriptor);
201	                final int pageCount = renderer.getPageCount();
202	                for (int i = 0; i < pageCount; i++) {
203	                    PdfRenderer.Page page = renderer.openPage(i);
204	                    Bitmap bitmap = Bitmap.createBitmap(page.getWidth(), page.getHeight(),
205	                            Bitmap.Config.ARGB_8888);
206	                    // say we render for showing on the screen
207	                    page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);
208	
209	                    // do stuff with the bitmap
210	                    bitmaps.add(bitmap);
211	                    // close the page
212	                    page.close();
213	                }
214	
215	                // close the renderer
216	                renderer.close();
217	            }
218	        } catch (IOException | SecurityException | IllegalArgumentException | OutOfMemoryError e) {
219	            e.printStackTrace();
220	        }
221	
222	        if (bitmaps.size() < 1) {
223	            showSnackbar(mActivity, R.string.file_access_error);
224	        } else {
225	            RearrangePdfPages.mImages = bitmaps;
226	            startActivityForResult(RearrangePdfPages.getStartIntent(mActivity),
227	                    INTENT_REQUEST_REARRANGE_PDF);
228	        }
229	
230	    }
