232	    private void compressPDF() {
233	        String input = pagesInput.getText().toString();
234	        int check;
235	        try {
236	            check = Integer.parseInt(String.valueOf(input));
237	            if (check > 100 || check <= 0) {
238	                showSnackbar(mActivity, R.string.invalid_entry);
239	            } else {
240	                String outputPath = mPath.replace(mActivity.getString(R.string.pdf_ext),
241	                        "_edited" + check + mActivity.getString(R.string.pdf_ext));
242	                mPDFUtils.compressPDF(mPath, outputPath, 100 - check, this);
243	            }
244	        } catch (NumberFormatException e) {
245	            showSnackbar(mActivity, R.string.invalid_entry);
246	        }
247	    }
